import{_ as l,D as i,o as t,c as p,j as e,a,I as n,w as s,am as r}from"./chunks/framework.DXw8qDd0.js";const v=JSON.parse('{"title":"Codex config.toml配置详解","description":"","frontmatter":{"title":"Codex config.toml配置详解","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex config.toml配置详解.md","filePath":"笔记/Codex/Codex config.toml配置详解.md"}'),c={name:"笔记/Codex/Codex config.toml配置详解.md"},d=e("h1",{id:"配置文件-config-toml-详解",tabindex:"-1"},[a("配置文件 config.toml 详解 "),e("a",{class:"header-anchor",href:"#配置文件-config-toml-详解","aria-label":'Permalink to "配置文件 config.toml 详解"'},"​")],-1),u=r(`<p>config.toml 用来保存 Codex CLI 的本地默认行为。你可以把它理解为&quot;个人驾驶舱&quot;：模型、审批、沙盒、profiles、MCP 服务等偏好都可以在这里集中管理。</p><hr><h2 id="配置文件放在哪里" tabindex="-1">配置文件放在哪里 <a class="header-anchor" href="#配置文件放在哪里" aria-label="Permalink to &quot;配置文件放在哪里&quot;">​</a></h2><p>通常位于：</p><p>~/.codex/config.toml</p><p>项目长期规则建议写到仓库内的 AGENTS.md，个人偏好放到本机 config.toml。这样团队成员能共享项目规则，又能保留自己的 CLI 使用习惯。</p><hr><h2 id="最小配置示例" tabindex="-1">最小配置示例 <a class="header-anchor" href="#最小配置示例" aria-label="Permalink to &quot;最小配置示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>model = &quot;gpt-5.1-codex-max&quot;</span></span>
<span class="line"><span>approval_policy = &quot;on-request&quot;</span></span>
<span class="line"><span>sandbox_mode = &quot;workspace-write&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[profiles.readonly]</span></span>
<span class="line"><span>approval_policy = &quot;on-request&quot;</span></span>
<span class="line"><span>sandbox_mode = &quot;read-only&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[profiles.build]</span></span>
<span class="line"><span>approval_policy = &quot;on-request&quot;</span></span>
<span class="line"><span>sandbox_mode = &quot;workspace-write&quot;</span></span></code></pre></div><p>这个示例表达三件事：</p><ul><li>默认允许在当前工作区写文件。</li><li>高风险命令仍需审批。</li><li>额外保留一个只读 profile，适合新仓库分析。</li></ul><hr><h2 id="常见配置项用途" tabindex="-1">常见配置项用途 <a class="header-anchor" href="#常见配置项用途" aria-label="Permalink to &quot;常见配置项用途&quot;">​</a></h2><ol><li><strong>模型</strong>：速度、成本、推理深度的取舍。建议用默认配置起步，复杂任务再临时调整。</li><li><strong>沙盒</strong>：Codex 能读写哪些位置。新手先只读或工作区写入。</li><li><strong>审批</strong>：哪些命令需要你确认。涉及网络、删除、安装、发布时保留审批。</li><li><strong>profiles</strong>：不同任务使用不同组合。建议准备 readonly、coding、review 三类 profile。</li><li><strong>MCP</strong>：接入外部工具和知识源。只接可信服务，明确权限范围。</li><li><strong>环境</strong>：传递必要变量或隔离敏感变量。凭证用最小权限，避免写进教程截图。</li></ol><hr><h2 id="推荐-profiles" tabindex="-1">推荐 profiles <a class="header-anchor" href="#推荐-profiles" aria-label="Permalink to &quot;推荐 profiles&quot;">​</a></h2><h3 id="只读学习" tabindex="-1">只读学习 <a class="header-anchor" href="#只读学习" aria-label="Permalink to &quot;只读学习&quot;">​</a></h3><p>适合打开陌生仓库、生成项目地图、梳理测试命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>[profiles.readonly]</span></span>
<span class="line"><span>sandbox_mode = &quot;read-only&quot;</span></span>
<span class="line"><span>approval_policy = &quot;on-request&quot;</span></span></code></pre></div><p>任务示例：请只读分析当前仓库。不要修改文件，不要运行会写入文件的命令。</p><h3 id="日常编码" tabindex="-1">日常编码 <a class="header-anchor" href="#日常编码" aria-label="Permalink to &quot;日常编码&quot;">​</a></h3><p>适合修测试、补文档、小范围实现。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>[profiles.coding]</span></span>
<span class="line"><span>sandbox_mode = &quot;workspace-write&quot;</span></span>
<span class="line"><span>approval_policy = &quot;on-request&quot;</span></span></code></pre></div><p>任务示例：请修复这个失败测试。修改范围限制在 src/parser 和对应测试文件，修复后运行 pnpm test parser。</p><h3 id="审查与发布前检查" tabindex="-1">审查与发布前检查 <a class="header-anchor" href="#审查与发布前检查" aria-label="Permalink to &quot;审查与发布前检查&quot;">​</a></h3><p>适合 PR review、发布前风险扫描、diff 检查。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>[profiles.review]</span></span>
<span class="line"><span>sandbox_mode = &quot;read-only&quot;</span></span>
<span class="line"><span>approval_policy = &quot;never&quot;</span></span></code></pre></div><p>任务示例：请审查最近一次改动，列出潜在风险、遗漏测试和建议改进点。不要修改任何文件。</p><hr><h2 id="团队配置建议" tabindex="-1">团队配置建议 <a class="header-anchor" href="#团队配置建议" aria-label="Permalink to &quot;团队配置建议&quot;">​</a></h2><p>适合进仓库的内容：</p><ul><li>AGENTS.md</li><li>推荐测试命令</li><li>代码风格和目录说明</li><li>PR 模板</li><li>文档截图规范</li></ul><p>适合留在个人机器的内容：</p><ul><li>默认模型偏好</li><li>本地路径</li><li>凭证、密钥、私有服务地址</li><li>个人 MCP 服务</li><li>私有 automation 配置</li></ul><hr><h2 id="排障清单" tabindex="-1">排障清单 <a class="header-anchor" href="#排障清单" aria-label="Permalink to &quot;排障清单&quot;">​</a></h2><ul><li>配置没生效：检查文件路径、TOML 语法、CLI 版本、启动时是否选择 profile。</li><li>Codex 权限超出预期：检查 sandbox_mode 和 approval_policy。</li><li>某个命令一直被拒绝：检查沙盒限制、网络权限和组织策略。</li><li>MCP 无法连接：检查服务命令、环境变量、端口、认证方式。</li></ul><hr>`,38);function h(m,f,g,q,_,b){const o=i("VPNolebaseInlineLinkPreview");return t(),p("div",null,[d,e("blockquote",null,[e("p",null,[a("来源：CodexGuide - config.toml ("),n(o,{href:"https://codexguide.ai/configuration/config-file.html",target:"_blank",rel:"noreferrer"},{default:s(()=>[a("https://codexguide.ai/configuration/config-file.html")]),_:1}),a(")")])]),u,e("blockquote",null,[e("p",null,[a("📎 "),n(o,{href:"/ocdsync/笔记/"},{default:s(()=>[a("📒 返回笔记索引")]),_:1})])])])}const k=l(c,[["render",h]]);export{v as __pageData,k as default};
